create table if not exists public.cms_site_settings(key text primary key check(key in('navigation','redirects','settings')),value jsonb not null default'{}',updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.cms_site_settings enable row level security;grant select,insert,update on public.cms_site_settings to authenticated;
drop policy if exists "CMS admins read site settings" on public.cms_site_settings;create policy "CMS admins read site settings" on public.cms_site_settings for select to authenticated using(exists(select 1 from public.cms_admins where user_id=auth.uid()));
drop policy if exists "CMS admins insert site settings" on public.cms_site_settings;create policy "CMS admins insert site settings" on public.cms_site_settings for insert to authenticated with check(updated_by=auth.uid()and exists(select 1 from public.cms_admins where user_id=auth.uid()));
drop policy if exists "CMS admins update site settings" on public.cms_site_settings;create policy "CMS admins update site settings" on public.cms_site_settings for update to authenticated using(exists(select 1 from public.cms_admins where user_id=auth.uid()))with check(updated_by=auth.uid()and exists(select 1 from public.cms_admins where user_id=auth.uid()));
